// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.proxy.config;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.Assertions.entry;

import java.util.List;
import java.util.Properties;
import java.util.Set;

import org.junit.jupiter.api.Test;

/**
 * The two namespace settings of workbench.properties: {@code namespaces}, which pages treat as if every repository had
 * stored them, and {@code namespaces.fallback}, which replaces the bundled (empty) list the query editor falls back on
 * for prefixes that are not defined.
 */
class WorkbenchNamespacePolicyTest {

	private static WorkbenchPolicy policy(String key, String value) {
		Properties properties = new Properties();
		properties.setProperty(key, value);
		return WorkbenchPolicy.fromProperties(properties, Set.of());
	}

	@Test
	void noNamespacesAreConfiguredByDefault() {
		assertThat(WorkbenchPolicy.fromProperties(new Properties(), Set.of()).getConfiguredNamespaces()).isEmpty();
		assertThat(policy("namespaces", "  ").getConfiguredNamespaces()).isEmpty();
	}

	@Test
	void configuredNamespacesKeepTheirOrderAndAcceptBracketsAndTheEmptyPrefix() {
		WorkbenchPolicy policy = policy("namespaces",
				"ex:http://example.org/ns# ,dcat:<http://www.w3.org/ns/dcat#>\n  :urn:default: list:<urn:a,b:>");

		assertThat(policy.getConfiguredNamespaces()).containsExactly(
				entry("ex", "http://example.org/ns#"),
				entry("dcat", "http://www.w3.org/ns/dcat#"),
				entry("", "urn:default:"),
				entry("list", "urn:a,b:"));
	}

	@Test
	void configuredNamespacesRejectMalformedEntries() {
		for (String invalid : List.of("ex", "1ex:http://example.org/", "ex:", "ex:relative/path",
				"ex:<http://example.org/", "ex:<http://example.org/ns# >", "ex:http://a/ ex:http://b/")) {
			assertThatThrownBy(() -> policy("namespaces", invalid))
					.as(invalid)
					.isInstanceOf(IllegalArgumentException.class)
					.hasMessageContaining("namespaces");
		}
	}

	@Test
	void fallbackNamespacesAreTheBundledEmptyListByDefault() {
		WorkbenchPolicy policy = WorkbenchPolicy.fromProperties(new Properties(), Set.of());

		assertThat(policy.getFallbackNamespaces()).isEmpty();
	}

	@Test
	void theFallbackSettingReplacesTheBundledList() {
		WorkbenchPolicy policy = policy("namespaces.fallback", "foaf:urn:my-foaf: acme:https://acme.example/vocab#");

		assertThat(policy.getFallbackNamespaces()).containsExactly(entry("foaf", "urn:my-foaf:"),
				entry("acme", "https://acme.example/vocab#"));
		assertThat(policy.getConfiguredNamespaces()).isEmpty();
	}

	@Test
	void anEmptyFallbackSettingTurnsTheFallbackOff() {
		assertThat(policy("namespaces.fallback", "").getFallbackNamespaces()).isEmpty();
	}

	@Test
	void theFallbackSettingRejectsMalformedEntries() {
		assertThatThrownBy(() -> policy("namespaces.fallback", "foaf"))
				.isInstanceOf(IllegalArgumentException.class)
				.hasMessageContaining("namespaces.fallback");
	}
}
